from money import amount, display
def summary(lines, discount):
    if discount < 0 or discount > 1:
        raise ValueError('Discount must be between 0 and 1')
    result = {}
    for line in lines:
        if line['quantity'] < 0 or line['unit_price'] < 0:
            raise ValueError('Quantity and price must be non-negative')
        total = amount(line['quantity']) * amount(line['unit_price']) * (1 - discount)
        result[line['sku']] = display(round(total, 2))
    return result

